templates.template:
variable "_module_source" {
  default = "git::https://github.com/Mia-Platform-Experiments/tf-aws-s3.git"
}

variable "service_name" {
  description = "The name of the service (e.g., payment-service-data). Used for S3 bucket naming. Must be 3-63 lowercase alphanumeric characters and hyphens. Note: S3 bucket names must be globally unique across all AWS accounts."
  type        = string
  default     = "%spec.service_name%"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$", var.service_name))
    error_message = "Service name must be 3-63 characters, lowercase alphanumeric and hyphens only, cannot start or end with a hyphen."
  }
}

variable "aws_region" {
  description = "The AWS region to deploy the S3 bucket."
  type        = string
  default     = "%spec.aws_region%"
}

variable "performance_profile" {
  description = "The performance tier selected by the developer (sandbox, development, production). Versioning and lifecycle rules are automatically configured based on this profile."
  type        = string
  default     = "%spec.performance_profile%"

  validation {
    condition     = contains(["sandbox", "development", "production"], var.performance_profile)
    error_message = "Performance profile must be one of: sandbox, development, production."
  }
}

variable "additional_tags" {
  description = "Additional tags to apply to the S3 bucket (optional)."
  type        = map(string)
  default     = %spec.additional_tags%
}
